CREATE OR REPLACE FUNCTION public.contract_scope_body(_template uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT regexp_replace(t.body,'(?s)SCHEDULE B — SERVICE SCOPE.*?(?=SIGNATURES|$)','SCHEDULE B — SERVICE SCOPE (version '||(SELECT max(scope_version)::text FROM service_scope WHERE service=t.service AND active)||')'||E'\n\n'||(SELECT string_agg(CASE WHEN section='included' THEN 'INCLUDED: ' ELSE 'NOT INCLUDED: ' END||CASE WHEN t.lang='es' THEN text_es ELSE text_en END,E'\n\n' ORDER BY CASE WHEN section='included' THEN 0 ELSE 1 END,sort_order) FROM service_scope WHERE service=t.service AND active AND section IN ('included','not_included'))||E'\n\n') FROM contract_templates t WHERE t.id=_template $$;
REVOKE ALL ON FUNCTION public.contract_scope_body(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.contract_scope_body(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.contract_commit_signature(_applicant uuid,_template uuid,_document uuid,_version text,_body text,_typed text,_business text,_ip text,_ua text,_path text,_values jsonb,_signed_at timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.applicants; s uuid; BEGIN
IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO a FROM public.applicants WHERE id=_applicant FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF; IF a.contracts_signed THEN RETURN jsonb_build_object('already',true); END IF;
IF NOT EXISTS(SELECT 1 FROM public.contractor_pipeline WHERE applicant_id=a.id AND proof_approved_at IS NOT NULL AND NOT archived AND state='open') THEN RAISE EXCEPTION 'equipment_approval_required'; END IF;
IF _template IS NOT NULL AND (a.contract_template_id IS DISTINCT FROM _template OR NOT EXISTS(SELECT 1 FROM public.contract_templates WHERE id=_template AND version=_version AND is_current) OR public.contract_scope_body(_template) IS DISTINCT FROM _body) THEN RAISE EXCEPTION 'template_changed'; END IF;
INSERT INTO public.contract_signatures(applicant_id,typed_name,signed_at,ip_address,user_agent,document_id,document_version,signed_pdf_path,template_id,template_service,template_body,business_name,pro_number,placeholder_values) VALUES(a.id,_typed,_signed_at,_ip,_ua,_document,_version,_path,_template,(SELECT service FROM public.contract_templates WHERE id=_template),_body,coalesce(nullif(_business,''),'—'),a.pro_number,_values) RETURNING id INTO s;
INSERT INTO public.company_documents(filename,category,tags,storage_path,mime_type,current_version,searchable_text) VALUES('ICA-signed-'||s::text||'.pdf','Contracts',ARRAY['signed','ica',a.id::text],_path,'application/pdf',true,_body);
INSERT INTO public.contractor_artifacts(applicant_id,kind,storage_path,filename) VALUES(a.id,'ica_signed',_path,'Tidy-Contractor-Agreement-signed.pdf');
UPDATE public.applicants SET contracts_signed=true,contracts_signed_at=_signed_at,contract_signed_name=_typed,contract_signed_ip=_ip,contract_signed_ua=_ua,contract_doc_version=_version,contract_signed_pdf_path=_path WHERE id=a.id;
INSERT INTO public.onboarding_events(applicant_id,event,metadata) VALUES(a.id,'contract_signed',jsonb_build_object('signature_id',s,'version',_version)); RETURN jsonb_build_object('ok',true,'signature_id',s); END $$;
REVOKE ALL ON FUNCTION public.contract_commit_signature(uuid,uuid,uuid,text,text,text,text,text,text,text,jsonb,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.contract_commit_signature(uuid,uuid,uuid,text,text,text,text,text,text,text,jsonb,timestamptz) TO service_role;